import{_ as t,o as a,c as s,a3 as o}from"./chunks/framework.BNNhFWPR.js";const u=JSON.parse('{"title":"MCP server","description":"Let an AI agent drive the editor or a running game through the Model Context Protocol.","frontmatter":{"id":"mcp-server","title":"MCP server","order":5,"description":"Let an AI agent drive the editor or a running game through the Model Context Protocol.","editUrl":"https://github.com/ATMO-Engine/atmo/edit/main/docs/en/manual/mcp-server.md"},"headers":[],"relativePath":"manual/mcp-server.md","filePath":"en/manual/mcp-server.md"}'),d={name:"manual/mcp-server.md"};function n(i,e,r,c,h,l){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="mcp-server" tabindex="-1">MCP server <a class="header-anchor" href="#mcp-server" aria-label="Permalink to &quot;MCP server&quot;">​</a></h1><p>The editor binary (<code>atmo</code>) can run a <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a> server. An MCP client, such as Claude Code, then edits scenes, materials and project settings, opens and closes editor tabs, takes viewport screenshots, runs the game and presses keys in it, reads the log and evaluates Luau. Exported games (<code>atmo-export</code>) never contain the server.</p><h2 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h2><p>The server is off by default. Either:</p><ul><li>start the engine with <code>--mcp [port]</code>, in the editor (<code>--project &lt;path&gt;</code>) or in run mode (<code>--project &lt;path&gt; --run</code>),</li><li>or enable <strong>MCP &gt; enabled</strong> in the project settings: the editor then starts the server every time it opens the project. The setting does not apply to run mode.</li></ul><p>The port comes from <code>--mcp &lt;port&gt;</code>, else from <strong>MCP &gt; port</strong> (27760 by default). The server listens on <code>http://127.0.0.1:&lt;port&gt;/mcp</code> only, with the Streamable HTTP transport, and refuses requests whose <code>Origin</code> header is not a local address.</p><p>To work without a window, add <code>--headless</code>. Headless mode uses the Null rendering platform, which draws nothing; add <code>--rendering-platform=metal</code> (macOS) or <code>--rendering-platform=vulkan</code> when the agent needs screenshots:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">atmo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headless</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rendering-platform=metal</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path/to/project</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mcp</span></span></code></pre></div><p>Headless mode runs at 60 frames per second instead of as fast as possible.</p><h2 id="connecting-claude-code" tabindex="-1">Connecting Claude Code <a class="header-anchor" href="#connecting-claude-code" aria-label="Permalink to &quot;Connecting Claude Code&quot;">​</a></h2><p>Start the engine first, then register the server once:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --transport</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> atmo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:27760/mcp</span></span></code></pre></div><p>or add it to the project&#39;s <code>.mcp.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;atmo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://127.0.0.1:27760/mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The client connects when it starts; if the engine was started later, reconnect with <code>/mcp</code>.</p><h2 id="editor-tools" tabindex="-1">Editor tools <a class="header-anchor" href="#editor-tools" aria-label="Permalink to &quot;Editor tools&quot;">​</a></h2><p>Paths are relative to the project root; <code>project://</code> paths and absolute paths work too. Tools that work on a scene take its file in <code>scene</code> and open a scene editor tab for it when none is open. Those tabs are marked <code>opened_by_mcp</code>, and <code>editor_close_auto</code> closes the ones without unsaved changes. Entities are addressed by their path below the scene root (<code>Player/Sprite</code>) or by the numeric id other tools return; <code>/</code> is the scene root.</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it does</th></tr></thead><tbody><tr><td><code>editor_types</code>, <code>editor_list</code></td><td>Editor types with their file extensions; open tabs (id, path, dirty, active).</td></tr><tr><td><code>editor_open</code></td><td>Open a file in the editor of its extension, or focus its tab; <code>create</code> a file.</td></tr><tr><td><code>editor_focus</code>, <code>editor_save</code>, <code>editor_close</code>, <code>editor_close_auto</code></td><td>Tab management. <code>editor_close</code> refuses to drop unsaved changes by default.</td></tr><tr><td><code>command_list</code>, <code>command_run</code></td><td>The editor commands (menus and shortcuts), except the ones that open dialogs.</td></tr><tr><td><code>entity_types</code>, <code>component_types</code></td><td>What <code>entity_create</code> and <code>component_set</code> accept, with component fields.</td></tr><tr><td><code>scene_tree</code>, <code>entity_get</code></td><td>The entity tree; one entity with all its component values.</td></tr><tr><td><code>entity_create</code>, <code>entity_delete</code>, <code>entity_rename</code>, <code>entity_reparent</code></td><td>Change the tree.</td></tr><tr><td><code>component_set</code>, <code>component_remove</code></td><td>Change component values (JSON merge patch) or remove a component.</td></tr><tr><td><code>entity_select</code></td><td>Select an entity in the scene editor&#39;s tree and inspector.</td></tr><tr><td><code>prefab_instantiate</code>, <code>prefab_save</code>, <code>scene_save</code></td><td>Prefab files and saving.</td></tr><tr><td><code>scene_screenshot</code></td><td>PNG of a scene editor viewport, with an optional size, center and zoom.</td></tr><tr><td><code>project_info</code>, <code>project_settings_get</code>, <code>project_settings_set</code></td><td>Project description and settings.</td></tr><tr><td><code>asset_tree</code></td><td>The project&#39;s files.</td></tr><tr><td><code>material_get</code>, <code>material_set</code>, <code>material_preview</code>, <code>shader_status</code></td><td>See <a href="/latest/manual/shaders-and-materials" class="atmo-ref atmo-ref--page" data-preview="Write Slang shaders for sprites and post-processing, and set their parameters with materials.">Shaders and materials</a>: parameters, values, a rendered preview, errors.</td></tr><tr><td><code>play_start</code>, <code>play_stop</code>, <code>play_status</code>, <code>game_tools</code>, <code>game_call</code></td><td>Run the game and call its tools (below).</td></tr><tr><td><code>luau_eval</code>, <code>logs_read</code></td><td>Evaluate Luau, read the log.</td></tr></tbody></table><p>The tab&#39;s dirty flag only tracks changes made through MCP tools; changes made with the mouse are not counted, so <code>editor_close</code> and <code>editor_close_auto</code> can close a tab with unsaved manual edits.</p><h2 id="running-the-game" tabindex="-1">Running the game <a class="header-anchor" href="#running-the-game" aria-label="Permalink to &quot;Running the game&quot;">​</a></h2><p><code>play_start</code> saves the modified tabs, then starts the game in a child process with <code>--mcp &lt;port + 1&gt;</code> (and <code>--headless</code> when asked). <code>game_call</code> forwards a tool call to it and <code>game_tools</code> lists its tools. Starting the game directly with <code>atmo --project &lt;path&gt; --run --mcp</code> gives the same tools without the editor:</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it does</th></tr></thead><tbody><tr><td><code>game_status</code></td><td>Frame, game time, pause state and the input names scripts use.</td></tr><tr><td><code>game_pause</code>, <code>game_resume</code></td><td>A paused game keeps running its systems with a delta time of 0.</td></tr><tr><td><code>game_step</code></td><td>Pause, run some frames with a fixed delta time (1/60 s by default), then answer.</td></tr><tr><td><code>game_input</code></td><td>Key, mouse button, wheel and text events, frames apart; a paused game is stepped through them.</td></tr><tr><td><code>game_action</code></td><td>Hold a named input (for example <code>Space</code>) for some frames.</td></tr><tr><td>scene tools, <code>luau_eval</code></td><td>Same as in the editor, on the running scene: leave <code>scene</code> out.</td></tr></tbody></table><p>Input goes through the same path as the window&#39;s events, so <code>Input.isJustPressed</code> sees it in the next frame.</p><h2 id="logs-and-luau" tabindex="-1">Logs and Luau <a class="header-anchor" href="#logs-and-luau" aria-label="Permalink to &quot;Logs and Luau&quot;">​</a></h2><p><code>logs_read</code> returns the last 2000 log entries (UTC times), from a sequence number on, so the agent can read only what is new. Luau&#39;s <code>print</code> writes to the log.</p><p><code>luau_eval</code> runs a Luau chunk in a new sandboxed thread of the scripting VM and returns its results as strings, the lines it printed and the log entries it produced. <code>entity</code> binds an entity to the global <code>this</code>, like in an entity script. The chunk can do anything a script can, including breaking the running state.</p>`,26)])])}const g=t(d,[["render",n]]);export{u as __pageData,g as default};
